import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function LudoBoard() {
  const navigate = useNavigate();

  // লোকাল স্টোরেজ থেকে গেম ডাটা রিড করা
  const [gameId, setGameId] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [entryFee, setEntryFee] = useState(null);
  const [status, setStatus] = useState("🎲 গেম লোড হচ্ছে...");

  useEffect(() => {
    const storedGameId = localStorage.getItem("gameId");
    const storedPlayerId = localStorage.getItem("playerId");
    const storedEntryFee = localStorage.getItem("entryFee");

    if (!storedGameId || !storedPlayerId) {
      setStatus("❌ কোনো গেম পাওয়া যায়নি, দয়া করে প্রথমে ম্যাচ শুরু করুন।");
      setTimeout(() => {
        navigate("/");
      }, 3000);
      return;
    }

    setGameId(storedGameId);
    setPlayerId(Number(storedPlayerId));
    setEntryFee(Number(storedEntryFee));
    setStatus("✅ গেম ডাটা লোড হয়েছে। খেলা শুরু করুন!");
  }, [navigate]);

  // এখানে তোমার লুডো গেমের মূল লজিক থাকবে
  // (যেমন: বোর্ড রেন্ডার, পিস চলানো, টার্ন ম্যানেজমেন্ট, websocket event ইত্যাদি)

  return (
    <div className="max-w-4xl mx-auto mt-10 p-6 bg-white border rounded-xl shadow-lg">
      <h1 className="text-3xl font-bold mb-6 text-center text-indigo-700">🎲 Ludo Game Board</h1>

      <div className="mb-4 text-center">
        <p><strong>গেম আইডি:</strong> {gameId || "N/A"}</p>
        <p><strong>প্লেয়ার নং:</strong> {playerId || "N/A"}</p>
        <p><strong>এন্ট্রি ফি:</strong> ৳ {entryFee || "N/A"}</p>
      </div>

      <div className="text-center mb-6 text-gray-700">{status}</div>

      {/* বোর্ডের UI এখানে তৈরি করবে */}
      <div className="border rounded p-4 bg-gray-50">
        {/* উদাহরণস্বরূপ, একটি সাদামাটা বোর্ড */}
        <p className="text-center text-gray-500 italic">[তোমার লুডো বোর্ডের UI এখানে থাকবে]</p>
      </div>

      {/* ফিরে যাওয়ার বাটন */}
      <div className="mt-6 text-center">
        <button
          onClick={() => navigate("/")}
          className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 transition"
        >
          🔙 ম্যাচে ফিরে যাও
        </button>
      </div>
    </div>
  );
}
